CREATE OR REPLACE FUNCTION public.public_cookie_sales() RETURNS TABLE(producto_id uuid, unidades bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT i.producto_id, sum(i.cantidad)::bigint FROM public.pedido_items i JOIN public.pedidos p ON p.id=i.pedido_id WHERE i.producto_id IS NOT NULL AND p.stripe_environment='live' AND p.monto_capturado > 0 AND p.estado NOT IN ('cancelado','reembolsado','pendiente','autorizado','autorizacion_fallida') GROUP BY i.producto_id ORDER BY sum(i.cantidad) DESC, i.producto_id $$; REVOKE ALL ON FUNCTION public.public_cookie_sales() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_cookie_sales() TO anon, authenticated, service_role;